import type { AnonymizationTier } from '../../src/types';

// Fixtures are deliberately loose: the scrubber changes value types (a name
// becomes null, an attachment list becomes a string).
type Json = any;

/** A fresh per-request pseudonym context, unsalted like upstream. */
function fresh(salt: string | null = null): PseudonymOptions {
  return { salt, memo: new Map() };
}

/** Upstream's `_anonymize_for_endpoint`: tier from the path, then that tier's treatment. */
function anonymizeForEndpoint(data: Json, path: string): { result: Json; tier: AnonymizationTier } {
  const tier = tierForPath(path);
  return { result: anonymizeResponse(data, { tier, path, ...fresh() }), tier };
}

// Sentinels that must never survive anonymization, in any nesting position.
const SENTINELS = ['jdoe2', 'Bob Smith', 'Alice Example', '@illinois.edu', '670001234', 'Doe, John'];

function expectNoPii(payload: unknown): void {
  const blob = JSON.stringify(payload);
  for (const sentinel of SENTINELS) {
    expect(blob, `PII leaked: ${sentinel}`).not.toContain(sentinel);
  }
}

/** Flatten a payload into { path: sorted keys } for key-set comparison. */
function collectKeySets(node: unknown, path = '$', found: Record<string, string[]> = {}): Record<string, string[]> {
  if (Array.isArray(node)) {
    node.forEach((item, index) => collectKeySets(item, `${path}[${index}]`, found));
  } else if (typeof node === 'object' && node !== null) {
    found[path] = Object.keys(node).sort();
    for (const [key, value] of Object.entries(node)) {
      collectKeySets(value, `${path}.${key}`, found);
    }
  }
  return found;
}

