// ---------------------------------------------------------------------------
// Pseudonyms
// ---------------------------------------------------------------------------

describe('generateAnonymousId', () => {
  it('matches upstream byte for byte when unsalted', () => {
    // hashlib.sha256(b"12345").hexdigest()[:8] == "5994471a"
    expect(generateAnonymousId(12345, 'Student', fresh())).toBe('Student_5994471a');
    expect(generateAnonymousId(101, 'Student', fresh())).toBe('Student_16dc368a');
    expect(generateAnonymousId(202, 'Student', fresh())).toBe('Student_c17edaae');
    expect(generateAnonymousId(0, 'Student', fresh())).toBe('Student_5feceb66');
    expect(generateAnonymousId('abc', 'Student', fresh())).toBe('Student_ba7816bf');
  });

  it('hashes the decimal string, so a numeric and a string id agree', () => {
    expect(generateAnonymousId('101', 'Student', fresh())).toBe(generateAnonymousId(101, 'Student', fresh()));
    expect(generateAnonymousId(101n, 'Student', fresh())).toBe('Student_16dc368a');
  });

  it('renders non-numeric ids the way Python str() does', () => {
    // hashlib.sha256(b"None") / b"True" / b"False"
    expect(generateAnonymousId(null, 'Student', fresh())).toBe('Student_dc937b59');
    expect(generateAnonymousId(undefined, 'Student', fresh())).toBe('Student_dc937b59');
    expect(generateAnonymousId(true, 'Student', fresh())).toBe('Student_3cbc87c7');
    expect(generateAnonymousId(false, 'Student', fresh())).toBe('Student_60a33e6c');
    expect(generateAnonymousId('sis:é', 'Student', fresh())).toBe('Student_522d9746');
  });

  it('switches to HMAC-SHA256 when a salt is given', () => {
    // hmac.new(b"pepper", b"12345", hashlib.sha256).hexdigest()[:8] == "e8b28b17"
    expect(generateAnonymousId(12345, 'Student', fresh('pepper'))).toBe('Student_e8b28b17');
    expect(generateAnonymousId(101, 'Student', fresh('pepper'))).toBe('Student_a3f1a1b9');
    expect(generateAnonymousId(101, 'Student', fresh('other salt'))).not.toBe('Student_a3f1a1b9');
  });

  it('treats an empty salt as no salt', () => {
    expect(generateAnonymousId(12345, 'Student', fresh(''))).toBe('Student_5994471a');
  });

  it('keeps prefixes apart in the memo (upstream collapses them)', () => {
    const pseudonyms = fresh();
    expect(generateAnonymousId(202, 'Student', pseudonyms)).toBe('Student_c17edaae');
    expect(generateAnonymousId(202, 'Reviewer', pseudonyms)).toBe('Reviewer_c17edaae');
    expect(generateAnonymousId(202, 'Reviewee', pseudonyms)).toBe('Reviewee_c17edaae');
    expect(generateAnonymousId(202, 'Student', pseudonyms)).toBe('Student_c17edaae');
    expect([...pseudonyms.memo.keys()]).toEqual(['Student:202', 'Reviewer:202', 'Reviewee:202']);
  });

  it('reads the memo before hashing', () => {
    const pseudonyms = fresh();
    pseudonyms.memo.set('Student:7', 'Student_from_memo');
    expect(generateAnonymousId(7, 'Student', pseudonyms)).toBe('Student_from_memo');
  });

  it('keeps no state outside the memo it is given', () => {
    const first = fresh('pepper');
    generateAnonymousId(101, 'Student', first);
    expect(first.memo.size).toBe(1);

    // A later request with a different salt must not see the first one's result.
    const second = fresh();
    expect(generateAnonymousId(101, 'Student', second)).toBe('Student_16dc368a');
    expect([...second.memo.keys()]).toEqual(['Student:101']);
  });

  it('gives different students different pseudonyms', () => {
    expect(generateAnonymousId(202, 'Student', fresh())).not.toBe(generateAnonymousId(101, 'Student', fresh()));
  });
});

// ---------------------------------------------------------------------------
// Free-text redaction
// ---------------------------------------------------------------------------

describe('scrubFreeText', () => {
  // [input, upstream scrub_free_text(input)]
  const PYTHON_CASES: Array<[string, string]> = [
    ['Nice work! Ping me at bob@illinois.edu or 217-555-0134.', 'Nice work! Ping me at [EMAIL_REDACTED] or [PHONE_REDACTED].'],
    ['SSN 123-45-6789 on file', 'SSN [SSN_REDACTED] on file'],
    ['call 2175550134 or 217.555.0134 or 217-555.0134', 'call [PHONE_REDACTED] or [PHONE_REDACTED] or [PHONE_REDACTED]'],
    ['12175550134', '12175550134'],
    ['x123-45-6789', 'x123-45-6789'],
    ['123-45-67890', '123-45-67890'],
    ['mail .foo@bar.com now', 'mail .[EMAIL_REDACTED] now'],
    ['a@b.com.x@y.org', '[EMAIL_REDACTED][EMAIL_REDACTED]'],
    ['first.last+tag@sub.example.co.uk,', '[EMAIL_REDACTED],'],
    ['user@host', 'user@host'],
    ['user@host.c', 'user@host.c'],
    ['user@host.com1', 'user@host.com1'],
    ['jdoe2@illinois.edu123-45-6789', 'jdoe2@illinois.edu123-45-6789'],
    ['123-45-6789@x.com', '[SSN_REDACTED]@x.com'],
    ['a@b.co 555-123-4567 999-88-7777 c_d@e.org', '[EMAIL_REDACTED] [PHONE_REDACTED] [SSN_REDACTED] [EMAIL_REDACTED]'],
    ['_under@score.com', '[EMAIL_REDACTED]'],
    ['', ''],
  ];

  it.each(PYTHON_CASES)('%j', (input, expected) => {
    expect(scrubFreeText(input)).toBe(expected);
  });

  describe('Unicode digits and word boundaries (Python \\d and \\b are Unicode-aware)', () => {
    const UNICODE_CASES: Array<[string, string, string]> = [
      ['full-width SSN', '１２３-４５-６７８９', '[SSN_REDACTED]'],
      ['Arabic-Indic phone', '٢١٧-٥٥٥-٠١٣٤', '[PHONE_REDACTED]'],
      ['full-width phone without separators', '２１７５５５０１３４', '[PHONE_REDACTED]'],
      ['Extended Arabic-Indic SSN and mixed-script phone', '۱۲۳-۴۵-۶۷۸۹ and 217٥٥٥0134', '[SSN_REDACTED] and [PHONE_REDACTED]'],
      ['a non-ASCII letter before digits is not a boundary', 'é123-45-6789', 'é123-45-6789'],
      ['a non-ASCII letter before an email start is not a boundary', 'éfoo.bar@x.com', 'éfoo[EMAIL_REDACTED]'],
      ['a non-ASCII letter after the TLD blocks the match', 'user@host.comé', 'user@host.comé'],
      ['a symbol before digits is a boundary', '№217-555-0134', '№[PHONE_REDACTED]'],
      ['a superscript digit before digits is a word character', '²217-555-0134', '²217-555-0134'],
      ['a superscript digit after digits is a word character', '217-555-0134²', '217-555-0134²'],
    ];

    it.each(UNICODE_CASES)('%s', (_label, input, expected) => {
      expect(scrubFreeText(input)).toBe(expected);
    });

    it('redacts astral-plane decimal digits', () => {
      // MATHEMATICAL BOLD DIGITS, outside the BMP.
      expect(scrubFreeText('call 𝟐𝟏𝟕-𝟓𝟓𝟓-𝟎𝟏𝟑𝟒 now')).toBe('call [PHONE_REDACTED] now');
      expect(scrubFreeText('😀217-555-0134😀')).toBe('😀[PHONE_REDACTED]😀');
    });
  });

  it('passes non-strings through untouched', () => {
    expect(scrubFreeText(null)).toBeNull();
    expect(scrubFreeText(42)).toBe(42);
    const list = ['a@b.com'];
    expect(scrubFreeText(list)).toBe(list);
  });

  it('is idempotent', () => {
    for (const [input] of PYTHON_CASES) {
      const once = scrubFreeText(input);
      expect(scrubFreeText(once)).toBe(once);
    }
  });

  it('agrees with a plain left-to-right regex replace of the three patterns', () => {
    // The email pass is a hand-written linear scan; this pins it to the
    // pattern it claims to implement.
    const steps = FREE_TEXT_REDACTIONS.map((step) => ({
      pattern: new RegExp(step.source, 'gu'),
      placeholder: step.placeholder,
    }));
    const reference = (text: string): string =>
      steps.reduce((current, step) => current.replace(step.pattern, step.placeholder), text);

    const tokens = [
      'a.b', 'jdoe2', '@', '@', 'x.com', 'illinois.edu', '.org', '.c', '.co1', '123', '45', '6789', '555', '0134',
      '217', '-', '-', '.', '.', ' ', ' ', 'é', '１２３', '４５', '６７８９', '٠١٢', '٣٤٥٦', '_', '%', '+', ',', '😀',
      'ü', 'COM', '9', 'x', '\n', '[', ']', ':', '/', '𝟏𝟐𝟑', '²',
    ];
    let seed = 0x1234567;
    const random = (): number => {
      seed ^= seed << 13;
      seed >>>= 0;
      seed ^= seed >>> 17;
      seed ^= seed << 5;
      seed >>>= 0;
      return seed / 0x100000000;
    };

    let redacted = 0;
    for (let i = 0; i < 20000; i += 1) {
      const length = 1 + Math.floor(random() * 12);
      let text = '';
      for (let j = 0; j < length; j += 1) {
        text += tokens[Math.floor(random() * tokens.length)];
      }
      const expected = reference(text);
      if (expected !== text) {
        redacted += 1;
      }
      expect(scrubFreeText(text)).toBe(expected);
    }
    // Guard against a generator that never produces a match.
    expect(redacted).toBeGreaterThan(100);
  });

  it('stays linear on a long run of local-part characters', () => {
    // A plain global regex retries from every "." here and takes minutes.
    const hostile = `${'a.'.repeat(150_000)} @ ${'a.'.repeat(150_000)}@`;
    const started = performance.now();
    expect(scrubFreeText(hostile)).toBe(hostile);
    expect(performance.now() - started).toBeLessThan(2000);
  });
});

