describe('enrollment records with a nested user', () => {
  it('anonymizes the nested user and fabricates nothing on the wrapper', () => {
    const enrollment = {
      id: 9001, // enrollment id, not a student id
      course_id: 123,
      type: 'StudentEnrollment',
      sis_user_id: '670001234',
      user: { id: 101, name: 'Alice Student', sortable_name: 'Student, Alice', login_id: 'alice1' },
    };
    // Upstream's anonymize_user_data: the record is treated as user context.
    const result: Json = scrubIdentity(enrollment, fresh(), { userContext: true });
    expect(result.user.name).not.toBe('Alice Student');
    expect(result.user.name).toMatch(/^Student_/);
    expect(result.user.id).toBe(101);
    expect(result).not.toHaveProperty('name');
    expect(result).not.toHaveProperty('email');
    expect(result.sis_user_id).toBeNull();
    expect(result.type).toBe('StudentEnrollment');
  });

  it('does not fabricate identity on a flat non-user record', () => {
    const result = scrubIdentity({ id: 9003, course_id: 123, type: 'StudentEnrollment' }, fresh(), { userContext: true });
    expect(result).toEqual({ id: 9003, course_id: 123, type: 'StudentEnrollment' });
  });

  it('anonymizes an enrollment list', () => {
    const enrollments = [{ id: 9002, user_id: 102, user: { id: 102, name: 'Bob Learner', login_id: 'bob2' } }];
    const result = anonymizeResponseData(enrollments, 'users', fresh());
    expect(result[0]!.user.name).not.toBe('Bob Learner');
  });
});

