describe('anonymization never adds a key', () => {
  it.each(FIXTURE_NAMES)('%s keeps every key set', (name) => {
    const result = anonymizeResponseData(fixture(name), 'submissions', fresh());
    expect(collectKeySets(result)).toEqual(collectKeySets(fixture(name)));
  });

  it.each<[string, () => Json, string]>([
    ['conversations', conversationsList, '/conversations'],
    ['pages', pagesList, '/pages'],
    ['discussion view', discussionView, '/courses/1/discussion_topics/2/view'],
    ['roster', usersWithEnrollments, '/courses/1/users'],
  ])('%s keeps every key set through its endpoint tier', (_label, build, path) => {
    expect(collectKeySets(anonymizeForEndpoint(build(), path).result)).toEqual(collectKeySets(build()));
  });

  it('a minimal user gains no fabricated fields', () => {
    const result = scrubIdentity({ id: 101, name: 'John Doe', login_id: 'jdoe2' }, fresh());
    expect(Object.keys(result).sort()).toEqual(['id', 'login_id', 'name']);
  });

  it('a record without content fields gains none from the submission refinement', () => {
    const result = anonymizeResponseData({ id: 1, user_id: 101, submitted_at: 'x' }, 'submissions', fresh());
    expect(Object.keys(result)).toEqual(['id', 'user_id', 'submitted_at']);
  });

  it('keeps a "__proto__" key as an ordinary own property', () => {
    const payload = JSON.parse('{"id": 101, "login_id": "jdoe2", "__proto__": {"email": "jdoe2@illinois.edu"}}');
    const result: Json = scrubIdentity(payload, fresh());
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(Object.keys(result).sort()).toEqual(['__proto__', 'id', 'login_id']);
    expectNoPii(result);
    expect(JSON.parse(JSON.stringify(result)).__proto__.email).toBe('student_16dc368a@example.edu');
  });
});

