describe('data type routing', () => {
  it('an explicit data type suppresses duck-typing', () => {
    // An assignment carrying a `message` key is not a discussion, and its
    // long description is still replaced.
    const assignment = {
      id: 42,
      name: 'Reflection Essay',
      due_at: '2026-03-01T23:59:00Z',
      message: 'See instructions',
      description: 'x'.repeat(1200),
    };
    const result = anonymizeResponseData(assignment, 'assignments', fresh());
    expect(result.description).toBe('[LONG_DESCRIPTION_REDACTED_FOR_PRIVACY]');
    expect(result.name).toBe('Reflection Essay');
  });

  it('the users type does not redact submission content', () => {
    const record = { id: 1, user_id: 101, submitted_at: '2026-03-01T00:00:00Z', body: 'hello' };
    expect(anonymizeResponseData(record, 'users', fresh()).body).toBe('hello');
  });

  it('an unknown data type falls back to duck-typing', () => {
    const record = { id: 1, user_id: 101, submitted_at: '2026-03-01T00:00:00Z', body: 'hello' };
    expect(anonymizeResponseData(record, 'general', fresh()).body).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
    expect(anonymizeResponseData(record, 'test_endpoint', fresh()).body).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
  });

  it('duck-typing prefers submitted_at, then due_at', () => {
    const both = { id: 1, user_id: 101, submitted_at: null, due_at: null, body: 'hi', description: 'x'.repeat(1001) };
    const result = anonymizeResponseData(both, 'general', fresh());
    expect(result.body).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
    expect(result.description).toHaveLength(1001);
  });
});

describe('submission content redaction', () => {
  it('redacts body and url per student and attachments generically', () => {
    const submission = {
      id: 7003,
      user_id: 101,
      body: 'My essay',
      url: 'https://example.com/my-work',
      attachments: [{ id: 88, display_name: 'essay.pdf' }],
    };
    expect(anonymizeResponseData(submission, 'submissions', fresh())).toEqual({
      id: 7003,
      user_id: 101,
      body: '[CONTENT_REDACTED_FOR_Student_16dc368a]',
      url: '[CONTENT_REDACTED_FOR_Student_16dc368a]',
      attachments: '[CONTENT_REDACTED]',
    });
  });

  it('leaves empty content fields as they are', () => {
    const submission = { id: 7003, user_id: 101, attachments: [], url: '', body: null };
    expect(anonymizeResponseData(submission, 'submissions', fresh())).toEqual(submission);
  });

  it('skips a record whose user_id is missing or falsy', () => {
    expect(anonymizeResponseData({ user_id: 0, submitted_at: 'x', body: 'hello a@b.com' }, 'submissions', fresh())).toEqual({
      user_id: 0,
      submitted_at: 'x',
      body: 'hello [EMAIL_REDACTED]',
    });
    expect(anonymizeResponseData({ id: 1, body: 'hello' }, 'submissions', fresh())).toEqual({ id: 1, body: 'hello' });
  });

  it('keys the placeholder to a string user_id the same way', () => {
    const record = { id: 1, user_id: '101', submitted_at: 'x', body: 'hi' };
    expect(anonymizeResponseData(record, 'general', fresh()).body).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
  });

  it('applies to records in nested lists but not to records nested inside a record', () => {
    const record = { id: 1, user_id: 101, submitted_at: 'x', body: 'hi' };
    expect(anonymizeResponseData([[record]], 'general', fresh())[0]![0]!.body).toBe(
      '[CONTENT_REDACTED_FOR_Student_16dc368a]',
    );
    // Upstream refines top-level records only; the nested body still gets the free-text scrub.
    const grouped = [{ user_id: 101, submissions: [{ ...record, body: 'my essay a@b.com' }] }];
    expect(anonymizeResponseData(grouped, 'submissions', fresh())[0]!.submissions[0]!.body).toBe(
      'my essay [EMAIL_REDACTED]',
    );
  });

  it('redacts another student’s submission but the gate exempts the caller’s own', () => {
    const submission = {
      id: 7004,
      user_id: 101,
      submitted_at: '2026-03-01T12:00:00Z',
      body: 'My own essay text',
      url: 'https://example.com/my-work',
    };
    const own = anonymizeForEndpoint(submission, '/courses/1/assignments/2/submissions/self');
    expect(own.tier).toBe('none');
    expect(own.result).toBe(submission);

    const other = anonymizeForEndpoint(submission, '/courses/1/assignments/2/submissions/101');
    expect(other.result.body).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
    expect(other.result.url).toBe('[CONTENT_REDACTED_FOR_Student_16dc368a]');
  });
});

describe('long assignment description redaction', () => {
  const describedBy = (description: unknown): Json =>
    anonymizeResponseData({ id: 1, due_at: null, description }, 'assignments', fresh()).description;

  it('replaces a description longer than 1000 characters', () => {
    expect(describedBy('x'.repeat(1001))).toBe('[LONG_DESCRIPTION_REDACTED_FOR_PRIVACY]');
  });

  it('keeps a description of exactly 1000 characters', () => {
    expect(describedBy('x'.repeat(1000))).toBe('x'.repeat(1000));
  });

  it('counts code points like Python, not UTF-16 units', () => {
    // 600 emoji are 1200 UTF-16 units but 600 characters.
    expect(describedBy('😀'.repeat(600))).toBe('😀'.repeat(600));
    expect(describedBy('😀'.repeat(1001))).toBe('[LONG_DESCRIPTION_REDACTED_FOR_PRIVACY]');
    expect(describedBy(`${'x'.repeat(999)}😀`)).toBe(`${'x'.repeat(999)}😀`);
    expect(describedBy(`${'x'.repeat(1000)}😀`)).toBe('[LONG_DESCRIPTION_REDACTED_FOR_PRIVACY]');
  });

  it('ignores non-string descriptions and other data types', () => {
    expect(describedBy(null)).toBeNull();
    expect(describedBy(['x'.repeat(2000)])).toEqual(['x'.repeat(2000)]);
    const record = { id: 3, description: 'x'.repeat(1001) };
    expect(anonymizeResponseData(record, 'general', fresh()).description).toHaveLength(1001);
    expect(anonymizeResponseData(record, 'users', fresh()).description).toHaveLength(1001);
  });
});

