describe('free_text tier on conversations', () => {
  const scrubbed = (): Json => {
    const { result, tier } = anonymizeForEndpoint(conversationsList(), '/conversations');
    expect(tier).toBe('free_text');
    return result[0];
  };

  it('redacts email and phone from the message preview', () => {
    const conversation = scrubbed();
    expect(conversation.last_message).not.toContain('jdoe2@illinois.edu');
    expect(conversation.last_message).toContain('[EMAIL_REDACTED]');
    expect(conversation.last_message).toContain('[PHONE_REDACTED]');
  });

  it('redacts email from the message body', () => {
    expect(scrubbed().messages[0].body).toContain('[EMAIL_REDACTED]');
  });

  it('keeps participant names', () => {
    const participant = scrubbed().participants[1];
    expect(participant.name).toBe('Carol Cee');
    expect(participant.full_name).toBe('Carol Cee');
  });

  it('still nulls direct identifiers', () => {
    const participant = scrubbed().participants[0];
    expect(participant.pronouns).toBeNull();
    expect(participant.avatar_url).toBeNull();
    expect(scrubbed().participants[1].pronouns).toBeNull();
  });

  it('keeps conversation metadata', () => {
    const conversation = scrubbed();
    expect(conversation.subject).toBe('Extension request');
    expect(conversation.workflow_state).toBe('unread');
    expect(conversation.last_authored_message).toBe('Sure - see you at office hours.');
  });
});

describe('identity tier on pages', () => {
  const scrubbed = (): Json => {
    const { result, tier } = anonymizeForEndpoint(pagesList(), '/courses/55/pages');
    expect(tier).toBe('identity');
    return result[0];
  };

  it('pseudonymises last_edited_by and keeps the id', () => {
    const editor = scrubbed().last_edited_by;
    expect(editor.display_name).toBe('Student_8bd9c0d4');
    expect(editor.id).toBe(303);
    expect(editor.avatar_image_url).toBeNull();
  });

  it('leaves the page body and metadata untouched', () => {
    const page = scrubbed();
    expect(page.body).toBe(pagesList()[0].body);
    expect(page.body).toContain('prof@illinois.edu');
    expect(page.title).toBe('Week 1 Overview');
    expect(page.url).toBe('week-1-overview');
    expect(page.published).toBe(true);
  });

  it('skips the typed refinements', () => {
    // A page-shaped record that would duck-type as a submission under `full`.
    const record = { id: 1, user_id: 101, submitted_at: 'x', body: 'kept', description: 'x'.repeat(1500), due_at: null };
    const result = anonymizeResponse(record, { tier: 'identity', path: '/courses/1/pages', ...fresh() });
    expect(result).toEqual(record);
  });
});

describe('the none tier', () => {
  it('returns the payload itself, unscrubbed', () => {
    const profile = selfProfile();
    const { result, tier } = anonymizeForEndpoint(profile, '/users/self/profile');
    expect(tier).toBe('none');
    expect(result).toBe(profile);
    expect(result.name).toBe('John Doe');
  });
});

describe('the two scrub flags are independent', () => {
  const record = (): Json => ({ id: 101, sortable_name: 'Doe, John', name: 'John Doe', body: 'Mail jdoe2@illinois.edu' });

  it('scrubs both by default', () => {
    const result = scrubIdentity(record(), fresh());
    expect(result.name).toMatch(/^Student_/);
    expect(result.body).toContain('[EMAIL_REDACTED]');
  });

  it('scrubText: false keeps only the body', () => {
    const result = scrubIdentity(record(), fresh(), { scrubText: false });
    expect(result.name).toMatch(/^Student_/);
    expect(result.body).toBe('Mail jdoe2@illinois.edu');
  });

  it('scrubDisplayNames: false keeps only the name', () => {
    const result = scrubIdentity(record(), fresh(), { scrubDisplayNames: false });
    expect(result.name).toBe('John Doe');
    expect(result.body).toContain('[EMAIL_REDACTED]');
  });

  it('strict and null fields apply under every flag combination', () => {
    const user = {
      id: 101,
      sortable_name: 'Doe, John',
      short_name: 'John',
      email: 'jdoe2@illinois.edu',
      login_id: 'jdoe2',
      sis_user_id: '670001234',
      avatar_url: 'https://canvas/avatars/101',
      pronouns: 'he/him',
    };
    for (const options of [{ scrubText: false }, { scrubDisplayNames: false }, { scrubText: false, scrubDisplayNames: false }]) {
      const result: Json = scrubIdentity(user, fresh(), options);
      expectNoPii(result);
      expect(result.sis_user_id).toBeNull();
      expect(result.avatar_url).toBeNull();
      expect(result.pronouns).toBeNull();
      expect(result.email).toBe('student_16dc368a@example.edu');
    }
  });

  it('flags propagate through nesting', () => {
    const payload = {
      a: [{ b: { user: { id: 101, login_id: 'jdoe2', name: 'John Doe', body: 'Mail jdoe2@illinois.edu' } } }],
    };
    const user = scrubIdentity(payload, fresh(), { scrubText: false, scrubDisplayNames: false }).a[0]!.b.user;
    expect(user.name).toBe('John Doe');
    expect(user.body).toBe('Mail jdoe2@illinois.edu');
    expect(user.login_id).toBe('student_16dc368a');
  });

  it('a bare-string user container follows the name flag', () => {
    const bare = { id: 1, user_id: 1, author: 'Bob Smith' };
    expect(scrubIdentity(bare, fresh(), { scrubDisplayNames: false }).author).toBe('Bob Smith');
    expect(scrubIdentity(bare, fresh()).author).toBe('Student_6b86b273');
  });

  it('inheritedId keys a record without an id to an enclosing user', () => {
    const result = scrubIdentity({ display_name: 'essay.pdf', author_name: 'John Doe' }, fresh(), { inheritedId: 101 });
    // display_name is ambiguous and this record carries no user signal of its own.
    expect(result).toEqual({ display_name: 'essay.pdf', author_name: 'Student_16dc368a' });
  });
});

// ---------------------------------------------------------------------------
// Salted pseudonyms through the scrubber
// ---------------------------------------------------------------------------

describe('salted scrubbing', () => {
  it('uses the HMAC pseudonym everywhere and never the unsalted one', () => {
    const path = '/courses/55/assignments/42/submissions';
    const result = anonymizeResponse(submissionsWithComments(), { tier: tierForPath(path), path, ...fresh('pepper') });
    expectNoPii(result);
    expect(result[0].body).toBe('[CONTENT_REDACTED_FOR_Student_a3f1a1b9]');
    expect(JSON.stringify(result)).not.toContain('16dc368a');
    expect(JSON.stringify(result)).not.toContain('c17edaae');
  });

  it('fills the caller’s memo, one entry per distinct student', () => {
    const pseudonyms = fresh('pepper');
    anonymizeResponse(submissionsWithComments(), { tier: 'full', path: '/courses/1/assignments/2/submissions', ...pseudonyms });
    expect([...pseudonyms.memo.keys()].sort()).toEqual(['Student:101', 'Student:202']);
  });
});
